CREATE TABLE reservations(id BINARY(16) PRIMARY KEY,tenant_id BINARY(16) NOT NULL,user_id BINARY(16) NOT NULL,charger_id BINARY(16) NOT NULL,connector_id BINARY(16) NOT NULL,reference VARCHAR(64) NOT NULL UNIQUE,status VARCHAR(20) NOT NULL,starts_at TIMESTAMP(6) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,created_at TIMESTAMP(6) NOT NULL,updated_at TIMESTAMP(6) NOT NULL);CREATE INDEX idx_reservations_tenant_start ON reservations(tenant_id,starts_at);CREATE INDEX idx_reservations_connector_window ON reservations(connector_id,status,starts_at,expires_at);
